CREATE TRIGGER policies_fts_ad AFTER DELETE ON policies BEGIN
  DELETE FROM policies_fts WHERE policy_id = old.id;
END

CREATE TRIGGER skills_fts_ad AFTER DELETE ON skills BEGIN
  DELETE FROM skills_fts WHERE skill_id = old.id;
END

CREATE TRIGGER skills_fts_au AFTER UPDATE ON skills BEGIN
  DELETE FROM skills_fts WHERE skill_id = old.id;
  INSERT INTO skills_fts(skill_id, name, invocation_guide)
  VALUES (new.id, new.name, new.invocation_guide);
END

CREATE TRIGGER traces_fts_ad AFTER DELETE ON traces BEGIN
  DELETE FROM traces_fts WHERE trace_id = old.id;
END

CREATE TRIGGER world_model_fts_ad AFTER DELETE ON world_model BEGIN
  DELETE FROM world_model_fts WHERE world_id = old.id;
END

CREATE TRIGGER world_model_fts_au AFTER UPDATE ON world_model BEGIN
  DELETE FROM world_model_fts WHERE world_id = old.id;
  INSERT INTO world_model_fts(world_id, title, body, domain_tags)
  VALUES (
    new.id,
    new.title,
    new.body,
    COALESCE(new.domain_tags_json, '')
  );
END

